import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.CmuCl-jw.js";const g=JSON.parse('{"title":"Storage","description":"","frontmatter":{},"headers":[],"relativePath":"apps/data/storage.md","filePath":"apps/data/storage.md"}'),s={name:"apps/data/storage.md"};function i(n,a,d,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to “Storage”">​</a></h1><p>On a self-hosted Arcsecond.local install, <strong>your data lives on your own infrastructure</strong>. There is no cloud bucket, no per-gigabyte billing and no storage quota — the only limit is the disk you give the install.</p><h2 id="where-data-is-stored" tabindex="-1">Where data is stored <a class="header-anchor" href="#where-data-is-stored" aria-label="Permalink to “Where data is stored”">​</a></h2><p>When you run <code>arcsecond setup</code>, you choose a host directory as the <code>SHARED_DATA_PATH</code>. Everything Arcsecond.local persists lives under it:</p><ul><li>uploaded datasets and data files,</li><li>generated 2D-image and 1D-spectrum previews,</li><li>the astrometry cache and temporary working files,</li><li>the hourly database backups (see <a href="/local/backups">Backups</a>).</li></ul><p>Because it is a plain directory on your machine, you back it up, snapshot it and size it with your own operational practice. The <a href="/local/backups">Backups</a> and <a href="/local/backups#what-else-to-back-up-off-host">disaster-recovery</a> guides cover what to copy off-host.</p><h2 id="how-data-is-organised" tabindex="-1">How data is organised <a class="header-anchor" href="#how-data-is-organised" aria-label="Permalink to “How data is organised”">​</a></h2><p>Data files are grouped into <strong><a href="./datasets">Datasets</a></strong> — virtual folders that collect files sharing a common source or interest, so they can be browsed and downloaded together. FITS and XISF files are parsed on ingestion: their headers are extracted for searching, and previews are generated.</p><h2 id="bringing-in-data-you-already-have" tabindex="-1">Bringing in data you already have <a class="header-anchor" href="#bringing-in-data-you-already-have" aria-label="Permalink to “Bringing in data you already have”">​</a></h2><p>You rarely start from a blank slate. Arcsecond.local can index data that already lives elsewhere — on an S3 bucket, a Dropbox, an FTP/SFTP server, another local disk, or an observatory archive — by attaching it as an <strong><a href="./external-storages">External Storage</a></strong>. Attached storages are read-only: Arcsecond.local scans and parses them exactly as it does its own data, never modifying anything.</p>',10)])])}const u=e(s,[["render",i]]);export{g as __pageData,u as default};
